import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE='http://localhost:8080'
start=datetime(2025,3,1,tzinfo=timezone.utc)
end=datetime(2025,6,1,tzinfo=timezone.utc)
token=None

def get_token():
    global token
    req=urllib.request.Request(BASE+'/token', method='POST')
    with urllib.request.urlopen(req, timeout=20) as r:
        token=[REDACTED_SECRET]'token']

def request(path):
    global token
    for attempt in range(30):
        if token is None: get_token()
        req=urllib.request.Request(BASE+path, headers={'Authorization':'Bearer '+token})
        try:
            with urllib.request.urlopen(req, timeout=20) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode('utf-8','replace')
            if e.code==401:
                token=None; continue
            if e.code==429:
                wait=None
                if e.headers.get('Retry-After'):
                    try: wait=float(e.headers['Retry-After'])
                    except ValueError: pass
                if wait is None:
                    try:
                        x=json.loads(body)
                        wait=float(x.get('retry_after') or x.get('wait') or x.get('retry_after_seconds'))
                    except Exception: wait=None
                if wait is None: wait=2
                time.sleep(wait); continue
            raise RuntimeError(f'{path}: HTTP {e.code}: {body}')
    raise RuntimeError('too many retries: '+path)

orders=[]
page=1
seen_listing_ids=set()
duplicates=0
while True:
    data=request('/orders?page='+str(page))
    items=data['items']
    for o in items:
        oid=o['id']
        if oid in seen_listing_ids:
            duplicates += 1
        else:
            seen_listing_ids.add(oid)
            orders.append(o)
    if not data.get('next'): break
    page += 1

customers={}
by={'north':0,'south':0,'east':0,'west':0}
count=0
for o in orders:
    if o['status'] "'!= '"'shipped': continue
    dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if not (start <= dt < end): continue
    cid=o['customer_id']
    if cid not in customers: customers[cid]=request('/customers/'+str(cid))
    c=customers[cid]
    discounted=(Decimal(o['amount_cents'])*(Decimal(100)-Decimal(c['discount_pct']))/Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by[c['region']] += int(discounted)
    count += 1
result={'total_cents':sum(by.values()),'order_count':count,'duplicates_skipped':duplicates,'by_region':by}
print(json.dumps({'pages':page,'unique_listed_orders':len(orders),'customers_fetched':len(customers),'result':result},sort_keys=True))
